import{_ as l,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2019-08-15 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-08-15 :: Ceph Performance Meeting","date":"2019-08-15T00:00:00.000Z","updated":"2019-08-16T00:00:00.000Z","tags":["Ceph性能","BlueStore优化","QoS功能","RBD兼容性","存储集群"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-08-15_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-08-15_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780459816000}'),i={name:"posts/2019/2019-08-15_-_-_Ceph_Performance_Meeting.md"};function n(u,e,s,p,_,a){return t(),r("div",null,[...e[0]||(e[0]=[o("<p>本次Ceph性能会议纪要概述了Ceph社区在性能优化、QoS功能实现、兼容性等方面的工作进展和讨论。</p><p><strong>一、本周工作进展</strong></p><ul><li><strong>BlueStore优化</strong>： <ul><li>Igor提交了优化BlueStore中设备空间利用的pull request，通过简化空间管理流程提高效率。</li><li>Sam提交了关于BlueStore QoS功能的pull request，并分析了BlueStore的NVMe性能，发现并发性对性能有显著影响。</li><li>Jinping提交了关于BlueStore锁定的pull request，旨在减少锁定，提高性能。</li><li>Egor提交了关于BlueStore性能优化的pull request，包括减少锁获取和更新finisher。</li><li>Adam继续推进BlueStore的优化工作，包括将IOU ring相关的工作移到后台运行，并对Object存储进行了优化。</li><li>Sonia探索了使用4K块大小的BlueStore性能，并进行Alligator aging测试的改进。</li></ul></li><li><strong>BlueStore QoS功能</strong>： <ul><li>讨论了如何实现BlueStore的QoS功能，以满足不同用户的需求。</li><li>讨论了如何通过节流值控制不同用户的I/O请求。</li></ul></li><li><strong>BlueStore与RBD的兼容性</strong>： <ul><li>讨论了如何确保BlueStore与RBD的兼容性。</li><li>讨论了如何处理不同存储引擎之间的性能差异。</li></ul></li></ul><p><strong>二、决定的事项</strong></p><ul><li>审查Igor的优化pull request。</li><li>将跟踪点集成到CDT中，并进行QoS实验。</li><li>继续推进BlueStore的优化工作，并与社区进行讨论。</li><li>与社区讨论4K块大小对BlueStore性能的影响。</li></ul><p><strong>三、后续行动计划</strong></p><ul><li>继续优化BlueStore的性能。</li><li>实现BlueStore的QoS功能。</li><li>确保BlueStore与RBD的兼容性。</li><li>对不同存储引擎进行性能测试。</li><li>改进BlueStore的Alligator aging测试。</li><li>进行更多关于4K块大小对BlueStore性能影响的测试。</li></ul><p><strong>总结</strong></p><p>本周Ceph社区在BlueStore性能优化、QoS功能实现等方面取得了进展，并讨论了后续的工作计划。社区将继续努力，为用户提供更好的存储解决方案。</p>",9)])])}const B=l(i,[["render",n]]);export{g as __pageData,B as default};
